starter.css:
.card { border: 1px solid #c9c4dc; border-left: 4px solid #5b3cc4; border-radius: 8px; padding: 8px 12px; margin-block-end: 12px; text-align: left; }
.card h3 { margin: 0 0 4px; }
.card p { margin: 0 0 4px; }
.badge { color: #5b3cc4; margin-right: 8px; }
.note { color: #595959; font-size: 0.9rem; }
.review { display: grid; gap: 4px; max-width: 320px; }
input, textarea { font: inherit; padding: 6px 8px; border: 1px solid #77708f; border-radius: 6px; }

solution.css:
.card { border: 1px solid #c9c4dc; border-inline-start: 4px solid #5b3cc4; border-radius: 8px; padding: 8px 12px; margin-block-end: 12px; text-align: start; }
.card h3 { margin: 0 0 4px; }
.card p { margin: 0 0 4px; }
.badge { color: #5b3cc4; margin-inline-end: 8px; }
.note { color: #595959; font-size: 0.9rem; }
.review { display: grid; gap: 4px; max-width: 320px; }
input, textarea { font: inherit; padding: 6px 8px; border: 1px solid #77708f; border-radius: 6px; }
